346	static int64_t ai_watch_elapsed_ms(FAR const struct timespec *now,
347	                                   FAR const struct timespec *then)
348	{
349	  return (int64_t)(now->tv_sec - then->tv_sec) * 1000 +
350	         (now->tv_nsec - then->tv_nsec) / 1000000;
351	}
352	
353	static bool ai_watch_deadline_reached(FAR const struct timespec *now,
354	                                      FAR const struct timespec *deadline)
355	{
356	  return now->tv_sec > deadline->tv_sec ||
357	         (now->tv_sec == deadline->tv_sec &&
358	          now->tv_nsec >= deadline->tv_nsec);
359	}
360	
361	static void ai_watch_advance_deadline(FAR struct timespec *deadline,
362	                                      long delay_ms)
363	{
364	  deadline->tv_nsec += delay_ms * 1000000;
365	  deadline->tv_sec += deadline->tv_nsec / 1000000000;
366	  deadline->tv_nsec %= 1000000000;
367	}
