369	static int ai_watch_day_of_week(int year, int month, int day)
370	{
371	  static const int t[] =
372	  {
373	    0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4
374	  };
375	
376	  if (month < 3)
377	    {
378	      year--;
379	    }
380	
381	  return (year + year / 4 - year / 100 + year / 400 +
382	          t[month - 1] + day) % 7;
383	}
