385	/****************************************************************************
386	 * Private Functions - Hex Menu: Coordinate System
387	 *
388	 * Hex ring layout: center (0,0), ring 1 has 6 positions, ring 2 has 12.
389	 * Positions use axial coordinates (col, row) mapped to 60-degree angles.
390	 *
391	 *   Ring 0:  1 icon   at (0,0)
392	 *   Ring 1:  6 icons  at 60-degree intervals
393	 *   Ring 2:  12 icons at 30-degree intervals
394	 *   Ring N:  6*N icons
395	 *
396	 * The total capacity is 1 + 6 + 12 = 19 icons for 2 rings.
397	 ****************************************************************************/
398	
399	static void ai_menu_hex_position(int index, float *out_x, float *out_y)
400	{
401	  float r;
402	  float angle_rad;
403	
404	  if (index == 0)
405	    {
406	      *out_x = 0.0f;
407	      *out_y = 0.0f;
408	      return;
409	    }
410	
411	  /* Find which ring this index belongs to */
412	
413	  if (index <= 6)
414	    {
415	      /* Ring 1: 6 positions at 60-degree intervals, starting at 90 degrees */
416	
417	      r = (float)AI_WATCH_MENU_RING_SPACING;
418	      angle_rad = (float)(index - 1) * (float)M_PI / 3.0f;
419	      *out_x = r * cosf(angle_rad);
420	      *out_y = r * sinf(angle_rad);
421	    }
422	  else
423	    {
424	      /* Ring 2: 12 positions at 30-degree intervals, offset by 15 degrees */
425	
426	      int idx2 = index - 7;
427	
428	      r = (float)AI_WATCH_MENU_RING_SPACING * 2.0f;
429	      angle_rad = (float)idx2 * (float)M_PI / 6.0f;
430	      *out_x = r * cosf(angle_rad);
431	      *out_y = r * sinf(angle_rad);
432	    }
433	}
