435	/****************************************************************************
436	 * Private Functions - Hex Menu: Transform & Rendering
437	 *
438	 * Pre-scaled icon tiers replace lv_img_set_zoom entirely:
439	 *   tier 0 = 160px (focused), tier 1 = 100px, tier 2 = 75px,
440	 *   tier 3 = 50px, tier 4 = 25px, tier -1 = hidden.
441	 *
442	 * Distance-squared thresholds (no sqrtf) select the tier.
443	 * Cached (x, y, tier, opa) per icon; LVGL setters called only on change.
444	 ****************************************************************************/
445	
446	/* Tier selection distance-squared thresholds (pixels²).
447	 * Tier 0: focused (always full opacity)
448	 * Tier 1: d² < 100²  → 100px, 100% opacity
449	 * Tier 2: d² < 180²  →  75px,  80% opacity
450	 * Tier 3: d² < 280²  →  50px,  50% opacity
451	 * Tier 4: d² < 400²  →  25px,  25% opacity
452	 * Beyond: hidden
453	 */
454	
455	#define MENU_D2_TIER1  (100.0f * 100.0f)
456	#define MENU_D2_TIER2  (180.0f * 180.0f)
457	#define MENU_D2_TIER3  (280.0f * 280.0f)
458	#define MENU_D2_HIDE   (400.0f * 400.0f)
459	
460	/* Icon pixel sizes per tier (must match generated icon dimensions) */
461	
462	static const int menu_tier_size[AI_WATCH_ICON_TIERS] =
463	{
464	  160, 100, 75, 50, 25
465	};
466	
467	/* Opacity per tier (percent of LV_OPA_COVER) */
468	
469	static const int menu_tier_opa_pct[AI_WATCH_ICON_TIERS] =
470	{
471	  100, 100, 80, 50, 25
472	};
473	
474	static void ai_menu_update_transform(FAR struct ai_watch_s *watch)
475	{
476	  FAR struct ai_menu_ctx_s *ctx = &watch->menu;
477	  float scr_cx = (float)AI_WATCH_SCREEN_WIDTH / 2.0f;
478	  float scr_cy = (float)AI_WATCH_SCREEN_HEIGHT / 2.0f;
479	  int new_focused;
480	  int i;
481	
482	  new_focused = ai_menu_find_nearest(watch);
483	
484	  for (i = 0; i < ctx->icon_count; i++)
485	    {
486	      FAR struct ai_menu_icon_s *icon = &ctx->icons[i];
487	      FAR const struct ai_app_desc_s *app;
488	      float screen_x;
489	      float screen_y;
490	      float dx;
491	      float dy;
492	      float d2;
493	      int tier;
494	      lv_opa_t opa;
495	      int ix;
496	      int iy;
497	      int half_size;
498	
499	      if (icon->img_obj == NULL)
500	        {
501	          continue;
502	        }
503	
504	      /* Icon screen position = base - scroll + center */
505	
506	      screen_x = icon->base_x - ctx->scroll_x + scr_cx;
507	      screen_y = icon->base_y - ctx->scroll_y + scr_cy;
508	
509	      /* Off-screen culling (generous margin for largest tier) */
510	
511	      if (screen_x < -170.0f ||
512	          screen_x > (float)AI_WATCH_SCREEN_WIDTH + 170.0f ||
513	          screen_y < -170.0f ||
514	          screen_y > (float)AI_WATCH_SCREEN_HEIGHT + 170.0f)
515	        {
516	          tier = -1;
517	        }
518	      else
519	        {
520	          dx = screen_x - scr_cx;
521	          dy = screen_y - scr_cy;
522	          d2 = dx * dx + dy * dy;
523	
524	          if (i == new_focused)
525	            {
526	              tier = 0;
527	            }
528	          else if (d2 < MENU_D2_TIER1)
529	            {
530	              tier = 1;
531	            }
532	          else if (d2 < MENU_D2_TIER2)
533	            {
534	              tier = 2;
535	            }
536	          else if (d2 < MENU_D2_TIER3)
537	            {
538	              tier = 3;
539	            }
540	          else if (d2 < MENU_D2_HIDE)
541	            {
542	              tier = 4;
543	            }
544	          else
545	            {
546	              tier = -1;
547	            }
548	        }
549	
550	      /* Hide completely */
551	
552	      if (tier < 0)
553	        {
554	          if (icon->last_tier >= 0)
555	            {
556	              lv_obj_add_flag(icon->img_obj, LV_OBJ_FLAG_HIDDEN);
557	              icon->last_tier = -1;
558	            }
559	
560	          continue;
561	        }
562	
563	      /* Compute opacity */
564	
565	      opa = (lv_opa_t)(LV_OPA_COVER * menu_tier_opa_pct[tier] / 100);
566	
567	      /* Pixel position (centered on screen point) */
568	
569	      half_size = menu_tier_size[tier] / 2;
570	      ix = (int)(screen_x) - half_size;
571	      iy = (int)(screen_y) - half_size;
572	
573	      /* Unhide if was hidden */
574	
575	      if (icon->last_tier < 0)
576	        {
577	          lv_obj_clear_flag(icon->img_obj, LV_OBJ_FLAG_HIDDEN);
578	        }
579	
580	      /* Switch image source if tier changed */
581	
582	      if (tier != icon->last_tier)
583	        {
584	          app = &g_app_registry[icon->app_index];
585	          lv_img_set_src(icon->img_obj, app->icon_tier[tier]);
586	          icon->last_tier = tier;
587	        }
588	
589	      /* Update position if changed */
590	
591	      if (ix != icon->last_x || iy != icon->last_y)
592	        {
593	          lv_obj_set_pos(icon->img_obj, ix, iy);
594	          icon->last_x = ix;
595	          icon->last_y = iy;
596	        }
597	
598	      /* Update opacity if changed */
599	
600	      if (opa != icon->last_opa)
601	        {
602	          lv_obj_set_style_opa(icon->img_obj, opa, 0);
603	          icon->last_opa = opa;
604	        }
605	    }
606	
607	  ctx->focused_index = new_focused;
608	}
609	
610	static int ai_menu_find_nearest(FAR struct ai_watch_s *watch)
611	{
612	  FAR struct ai_menu_ctx_s *ctx = &watch->menu;
613	  float scr_cx = (float)AI_WATCH_SCREEN_WIDTH / 2.0f;
614	  float scr_cy = (float)AI_WATCH_SCREEN_HEIGHT / 2.0f;
615	  float min_dist = 1e30f;
616	  int nearest = 0;
617	  int i;
618	
619	  for (i = 0; i < ctx->icon_count; i++)
620	    {
621	      float screen_x;
622	      float screen_y;
623	      float dx;
624	      float dy;
625	      float dist;
626	
627	      screen_x = ctx->icons[i].base_x - ctx->scroll_x + scr_cx;
628	      screen_y = ctx->icons[i].base_y - ctx->scroll_y + scr_cy;
629	      dx = screen_x - scr_cx;
630	      dy = screen_y - scr_cy;
631	      dist = dx * dx + dy * dy;
632	
633	      if (dist < min_dist)
634	        {
635	          min_dist = dist;
636	          nearest = i;
637	        }
638	    }
639	
640	  return nearest;
641	}
