643	/****************************************************************************
644	 * Private Functions - Hex Menu: Snap Animation
645	 *
646	 * Two separate exec callbacks:
647	 *   - ai_menu_snap_exec_x_cb: updates scroll_x only (no transform).
648	 *   - ai_menu_snap_exec_y_cb: updates scroll_y and calls transform
649	 *     once per frame.  user_data carries the watch pointer.
650	 ****************************************************************************/
651	
652	static void ai_menu_snap_exec_x_cb(void *var, int32_t value)
653	{
654	  *(FAR float *)var = (float)value;
655	}
656	
657	static void ai_menu_snap_exec_y_cb(void *var, int32_t value)
658	{
659	  FAR lv_anim_t *a;
660	
661	  *(FAR float *)var = (float)value;
662	
663	  /* Retrieve watch from user_data and refresh transform */
664	
665	  a = lv_anim_get(var, ai_menu_snap_exec_y_cb);
666	  if (a != NULL)
667	    {
668	      FAR struct ai_watch_s *w = lv_anim_get_user_data(a);
669	
670	      if (w != NULL)
671	        {
672	          ai_menu_update_transform(w);
673	        }
674	    }
675	}
676	
677	static void ai_menu_snap_ready_cb(lv_anim_t *a)
678	{
679	  FAR struct ai_watch_s *w = lv_anim_get_user_data(a);
680	
681	  if (w != NULL)
682	    {
683	      w->menu.snapping = false;
684	      ai_menu_update_transform(w);
685	    }
686	}
