688	static void ai_menu_start_snap(FAR struct ai_watch_s *watch, int index)
689	{
690	  FAR struct ai_menu_ctx_s *ctx = &watch->menu;
691	  float target_x;
692	  float target_y;
693	  lv_anim_t a;
694	
695	  if (index < 0 || index >= ctx->icon_count)
696	    {
697	      return;
698	    }
699	
700	  target_x = ctx->icons[index].base_x;
701	  target_y = ctx->icons[index].base_y;
702	
703	  ctx->snapping = true;
704	
705	  /* Animate scroll_x — no transform refresh */
706	
707	  lv_anim_init(&a);
708	  lv_anim_set_var(&a, &ctx->scroll_x);
709	  lv_anim_set_values(&a, (int32_t)ctx->scroll_x,
710	                     (int32_t)target_x);
711	  lv_anim_set_time(&a, AI_WATCH_MENU_SNAP_MS);
712	  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
713	  lv_anim_set_exec_cb(&a, ai_menu_snap_exec_x_cb);
714	  lv_anim_start(&a);
715	
716	  /* Animate scroll_y — exec callback also refreshes transform */
717	
718	  lv_anim_init(&a);
719	  lv_anim_set_var(&a, &ctx->scroll_y);
720	  lv_anim_set_values(&a, (int32_t)ctx->scroll_y,
721	                     (int32_t)target_y);
722	  lv_anim_set_time(&a, AI_WATCH_MENU_SNAP_MS);
723	  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
724	  lv_anim_set_exec_cb(&a, ai_menu_snap_exec_y_cb);
725	  lv_anim_set_user_data(&a, watch);
726	  lv_anim_set_ready_cb(&a, ai_menu_snap_ready_cb);
727	  lv_anim_start(&a);
728	
729	  ai_menu_update_transform(watch);
730	}
