732	/****************************************************************************
733	 * Private Functions - Hex Menu: Event Handling
734	 ****************************************************************************/
735	
736	static void ai_menu_event_cb(lv_event_t *e)
737	{
738	  FAR struct ai_watch_s *watch = lv_event_get_user_data(e);
739	  FAR struct ai_menu_ctx_s *ctx = &watch->menu;
740	  lv_event_code_t code = lv_event_get_code(e);
741	  FAR lv_indev_t *indev;
742	  lv_point_t point;
743	
744	  indev = lv_indev_get_act();
745	  if (indev == NULL)
746	    {
747	      return;
748	    }
749	
750	  lv_indev_get_point(indev, &point);
751	
752	  if (code == LV_EVENT_PRESSED)
753	    {
754	      /* Stop any running snap animation */
755	
756	      if (ctx->snapping)
757	        {
758	          lv_anim_del(&ctx->scroll_x, NULL);
759	          lv_anim_del(&ctx->scroll_y, NULL);
760	          ctx->snapping = false;
761	        }
762	
763	      ctx->dragging = false;
764	      ctx->drag_start_x = point.x;
765	      ctx->drag_start_y = point.y;
766	      ctx->drag_start_scroll_x = ctx->scroll_x;
767	      ctx->drag_start_scroll_y = ctx->scroll_y;
768	    }
769	  else if (code == LV_EVENT_PRESSING)
770	    {
771	      int dx = point.x - ctx->drag_start_x;
772	      int dy = point.y - ctx->drag_start_y;
773	      int threshold = 10;
774	      float new_scroll_x;
775	      float new_scroll_y;
776	      float delta_x;
777	      float delta_y;
778	
779	      /* Start dragging after threshold */
780	
781	      if (!ctx->dragging &&
782	          (abs(dx) > threshold || abs(dy) > threshold))
783	        {
784	          ctx->dragging = true;
785	        }
786	
787	      if (ctx->dragging)
788	        {
789	          new_scroll_x = ctx->drag_start_scroll_x - (float)dx;
790	          new_scroll_y = ctx->drag_start_scroll_y - (float)dy;
791	
792	          /* Skip refresh if movement is too small */
793	
794	          delta_x = new_scroll_x - ctx->last_render_scroll_x;
795	          delta_y = new_scroll_y - ctx->last_render_scroll_y;
796	
797	          if (delta_x * delta_x + delta_y * delta_y <
798	              (float)(AI_WATCH_MENU_DRAG_THRESH *
799	                      AI_WATCH_MENU_DRAG_THRESH))
800	            {
801	              return;
802	            }
803	
804	          ctx->scroll_x = new_scroll_x;
805	          ctx->scroll_y = new_scroll_y;
806	          ctx->last_render_scroll_x = new_scroll_x;
807	          ctx->last_render_scroll_y = new_scroll_y;
808	          ai_menu_update_transform(watch);
809	        }
810	    }
811	  else if (code == LV_EVENT_RELEASED ||
812	           code == LV_EVENT_PRESS_LOST)
813	    {
814	      if (ctx->dragging)
815	        {
816	          /* Drag ended: snap to nearest icon */
817	
818	          int nearest = ai_menu_find_nearest(watch);
819	
820	          ai_menu_start_snap(watch, nearest);
821	          ctx->dragging = false;
822	        }
823	      else
824	        {
825	          /* Tap (no drag): find which icon was tapped */
826	
827	          float scr_cx = (float)AI_WATCH_SCREEN_WIDTH / 2.0f;
828	          float scr_cy = (float)AI_WATCH_SCREEN_HEIGHT / 2.0f;
829	          int i;
830	
831	          for (i = 0; i < ctx->icon_count; i++)
832	            {
833	              float sx = ctx->icons[i].base_x - ctx->scroll_x + scr_cx;
834	              float sy = ctx->icons[i].base_y - ctx->scroll_y + scr_cy;
835	              float dx = (float)point.x - sx;
836	              float dy = (float)point.y - sy;
837	              float r = (float)AI_WATCH_MENU_ICON_SIZE * 0.4f;
838	
839	              if (dx * dx + dy * dy < r * r)
840	                {
841	                  if (i == ctx->focused_index)
842	                    {
843	                      /* Tapped the focused icon: launch app */
844	
845	                      ai_watch_open_app(watch,
846	                                        ctx->icons[i].app_index);
847	                    }
848	                  else
849	                    {
850	                      /* Tapped a non-focused icon: snap to it */
851	
852	                      ai_menu_start_snap(watch, i);
853	                    }
854	
855	                  break;
856	                }
857	            }
858	        }
859	    }
860	}
