1046	
1047	static void ai_watch_page_manager_init(FAR struct ai_watch_s *watch)
1048	{
1049	  watch->page_stack_top = 0;
1050	  watch->current_page = AI_WATCH_PAGE_HOME;
1051	  watch->app_page_screen = NULL;
1052	  watch->active_app_index = -1;
1053	  watch->page_stack[0] = AI_WATCH_PAGE_HOME;
1054	}
1055	
1056	static void ai_watch_push_page(FAR struct ai_watch_s *watch, int page)
1057	{
1058	  FAR lv_obj_t *target = NULL;
1059	  lv_scr_load_anim_t anim;
1060	
1061	  if (watch->page_stack_top >= AI_WATCH_PAGE_STACK_MAX - 1)
1062	    {
1063	      printf("ERROR: Page stack overflow\n");
1064	      return;
1065	    }
1066	
1067	  if (page < AI_WATCH_PAGE_FIXED_COUNT)
1068	    {
1069	      target = watch->fixed_pages[page];
1070	    }
1071	  else if (page == AI_WATCH_PAGE_APP_BASE &&
1072	           watch->app_page_screen != NULL)
1073	    {
1074	      target = watch->app_page_screen;
1075	    }
1076	
1077	  if (target == NULL)
1078	    {
1079	      return;
1080	    }
1081	
1082	  watch->page_stack_top++;
1083	  watch->page_stack[watch->page_stack_top] = page;
1084	  watch->current_page = page;
1085	
1086	  anim = (page == AI_WATCH_PAGE_APP_LIST) ?
1087	         LV_SCR_LOAD_ANIM_FADE_ON :
1088	         LV_SCR_LOAD_ANIM_MOVE_LEFT;
1089	
1090	  lv_scr_load_anim(target, anim, 200, 0, false);
1091	  printf("Push page %d (stack depth %d)\n", page,
1092	         watch->page_stack_top);
1093	}
1094	
1095	static void ai_watch_pop_page(FAR struct ai_watch_s *watch)
1096	{
1097	  int prev_page;
1098	  FAR lv_obj_t *target;
1099	  lv_scr_load_anim_t anim;
1100	
1101	  if (watch->page_stack_top <= 0)
1102	    {
1103	      return;
1104	    }
1105	
1106	  watch->page_stack_top--;
1107	  prev_page = watch->page_stack[watch->page_stack_top];
1108	
1109	  /* If leaving a dynamic app page, mark for cleanup but do NOT delete
1110	   * the screen object yet -- lv_scr_load_anim will switch away from it
1111	   * and the old screen is auto-deleted by LVGL after animation.
1112	   * We just clear our reference so a new app page can be created later.
1113	   */
1114	
1115	  if (watch->current_page == AI_WATCH_PAGE_APP_BASE)
1116	    {
1117	      if (watch->active_app_index >= 0 &&
1118	          watch->active_app_index < (int)AI_WATCH_APP_COUNT &&
1119	          g_app_registry[watch->active_app_index].destroy_cb != NULL)
1120	        {
1121	          g_app_registry[watch->active_app_index].destroy_cb(watch);
1122	        }
1123	
1124	      watch->app_page_screen = NULL;
1125	      watch->active_app_index = -1;
1126	    }
1127	
1128	  if (prev_page < AI_WATCH_PAGE_FIXED_COUNT)
1129	    {
1130	      target = watch->fixed_pages[prev_page];
1131	    }
1132	  else
1133	    {
1134	      return;
1135	    }
1136	
1137	  if (target == NULL)
1138	    {
1139	      return;
1140	    }
1141	
1142	  watch->current_page = prev_page;
1143	
1144	  anim = (prev_page == AI_WATCH_PAGE_HOME) ?
1145	         LV_SCR_LOAD_ANIM_FADE_ON :
1146	         LV_SCR_LOAD_ANIM_MOVE_RIGHT;
1147	
1148	  lv_scr_load_anim(target, anim, 200, 0, false);
1149	  printf("Pop to page %d (stack depth %d)\n", prev_page,
1150	         watch->page_stack_top);
1151	}
