1153	static void ai_watch_open_app(FAR struct ai_watch_s *watch, int app_index)
1154	{
1155	  const struct ai_app_desc_s *app;
1156	
1157	  if (app_index < 0 || app_index >= (int)AI_WATCH_APP_COUNT)
1158	    {
1159	      return;
1160	    }
1161	
1162	  app = &g_app_registry[app_index];
1163	
1164	  /* Special case: Settings uses the pre-created settings page */
1165	
1166	  if (app_index == 3)
1167	    {
1168	      ai_watch_push_page(watch, AI_WATCH_PAGE_SETTINGS);
1169	      return;
1170	    }
1171	
1172	  if (!app->available || app->create_cb == NULL)
1173	    {
1174	      FAR lv_obj_t *msgbox = lv_msgbox_create(NULL);
1175	
1176	      lv_msgbox_add_title(msgbox, "Coming Soon");
1177	      lv_msgbox_add_text(msgbox, "This app is under development.");
1178	      lv_msgbox_add_close_button(msgbox);
1179	      return;
1180	    }
1181	
1182	  app->create_cb(watch);
1183	
1184	  if (watch->app_page_screen != NULL)
1185	    {
1186	      watch->active_app_index = app_index;
1187	      watch->page_stack_top++;
1188	      watch->page_stack[watch->page_stack_top] =
1189	          AI_WATCH_PAGE_APP_BASE;
1190	      watch->current_page = AI_WATCH_PAGE_APP_BASE;
1191	
1192	      lv_scr_load_anim(watch->app_page_screen,
1193	                       LV_SCR_LOAD_ANIM_MOVE_LEFT, 200, 0, false);
1194	      printf("Opened app: %s\n", app->name);
1195	    }
1196	}
