1210	
1211	  if (watch->timer.running)
1212	    {
1213	      total_ms = watch->timer.elapsed_ms +
1214	                 (lv_tick_get() - watch->timer.start_tick);
1215	    }
1216	  else
1217	    {
1218	      total_ms = watch->timer.elapsed_ms;
1219	    }
