1221	  minutes = total_ms / 60000;
1222	  seconds = (total_ms % 60000) / 1000;
1223	  centiseconds = (total_ms % 1000) / 10;
1224	
1225	  snprintf(buf, sizeof(buf), "%02lu:%02lu.%02lu",
1226	           (unsigned long)minutes,
1227	           (unsigned long)seconds,
1228	           (unsigned long)centiseconds);
1229	  lv_label_set_text(watch->timer.time_label, buf);
1230	}
