1572	/****************************************************************************
1573	 * Private Functions - App List Page (Hex Ring Menu)
1574	 ****************************************************************************/
1575	
1576	static void ai_watch_create_app_list_page(FAR struct ai_watch_s *watch)
1577	{
1578	  FAR struct ai_menu_ctx_s *ctx = &watch->menu;
1579	  FAR lv_obj_t *screen;
1580	  int theme = watch->current_theme;
1581	  int app_count = (int)AI_WATCH_APP_COUNT;
1582	  int max_icons;
1583	  int i;
1584	
1585	  /* Create screen */
1586	
1587	  screen = lv_obj_create(NULL);
1588	  lv_obj_set_style_bg_color(screen, ai_watch_theme_bg(theme), 0);
1589	  lv_obj_set_scrollbar_mode(screen, LV_SCROLLBAR_MODE_OFF);
1590	  watch->app_list_screen = screen;
1591	  watch->fixed_pages[AI_WATCH_PAGE_APP_LIST] = screen;
1592	
1593	  /* Initialize menu context */
1594	
1595	  memset(ctx, 0, sizeof(*ctx));
1596	  ctx->focused_index = 0;
1597	  ctx->scroll_x = 0.0f;
1598	  ctx->scroll_y = 0.0f;
1599	
1600	  /* Create a transparent container covering the full screen.
1601	   * This is the touch target for drag events.
1602	   */
1603	
1604	  ctx->container = lv_obj_create(screen);
1605	  lv_obj_set_size(ctx->container, AI_WATCH_SCREEN_WIDTH,
1606	                  AI_WATCH_SCREEN_HEIGHT);
1607	  lv_obj_set_style_bg_opa(ctx->container, LV_OPA_TRANSP, 0);
1608	  lv_obj_set_style_border_width(ctx->container, 0, 0);
1609	  lv_obj_set_style_pad_all(ctx->container, 0, 0);
1610	  lv_obj_set_scrollbar_mode(ctx->container, LV_SCROLLBAR_MODE_OFF);
1611	  lv_obj_clear_flag(ctx->container, LV_OBJ_FLAG_SCROLLABLE);
1612	  lv_obj_add_event_cb(ctx->container, ai_menu_event_cb,
1613	                      LV_EVENT_PRESSED, watch);
1614	  lv_obj_add_event_cb(ctx->container, ai_menu_event_cb,
1615	                      LV_EVENT_PRESSING, watch);
1616	  lv_obj_add_event_cb(ctx->container, ai_menu_event_cb,
1617	                      LV_EVENT_RELEASED, watch);
1618	  lv_obj_add_event_cb(ctx->container, ai_menu_event_cb,
1619	                      LV_EVENT_PRESS_LOST, watch);
1620	
1621	  /* Place app icons in hex ring layout (1 + 6 + 12) */
1622	
1623	  max_icons = (app_count < AI_WATCH_MENU_MAX_ICONS) ?
1624	              app_count : AI_WATCH_MENU_MAX_ICONS;
1625	  ctx->icon_count = max_icons;
1626	
1627	  for (i = 0; i < max_icons; i++)
1628	    {
1629	      FAR const struct ai_app_desc_s *app = &g_app_registry[i];
1630	      FAR lv_obj_t *img;
1631	      float hx;
1632	      float hy;
1633	
1634	      /* Compute hex position */
1635	
1636	      ai_menu_hex_position(i, &hx, &hy);
1637	
1638	      ctx->icons[i].base_x = hx;
1639	      ctx->icons[i].base_y = hy;
1640	      ctx->icons[i].app_index = i;
1641	      ctx->icons[i].last_x = -9999;
1642	      ctx->icons[i].last_y = -9999;
1643	      ctx->icons[i].last_tier = -1;   /* starts hidden */
1644	      ctx->icons[i].last_opa = 0;
1645	
1646	      /* Create LVGL image object — starts hidden until first transform */
1647	
1648	      img = lv_img_create(screen);
1649	      lv_img_set_src(img, app->icon_tier[1]);  /* default: 100px tier */
1650	      lv_obj_set_style_opa(img, LV_OPA_TRANSP, 0);
1651	      lv_obj_add_flag(img, LV_OBJ_FLAG_HIDDEN);
1652	      lv_obj_add_flag(img, LV_OBJ_FLAG_EVENT_BUBBLE);
1653	
1654	      ctx->icons[i].img_obj = img;
1655	    }
1656	
1657	  /* Initial transform */
1658	
1659	  ai_menu_update_transform(watch);
1660	}
