1662	/****************************************************************************
1663	 * Private Functions - About/Init
1664	 ****************************************************************************/
1665	
1666	static void ai_watch_init_about(FAR struct ai_watch_s *watch)
1667	{
1668	  char about[128];
1669	  struct timespec ts;
1670	  struct tm tm;
1671	  bool rtc_ok = false;
1672	
1673	  if (clock_gettime(CLOCK_REALTIME, &ts) == 0 &&
1674	      localtime_r(&ts.tv_sec, &tm) != NULL &&
1675	      tm.tm_year + 1900 >= AI_WATCH_RTC_MIN_YEAR)
1676	    {
1677	      char time[16];
1678	
1679	      strftime(time, sizeof(time), "%H:%M:%S", &tm);
1680	      snprintf(about, sizeof(about),
1681	               "AI Watch v" AI_WATCH_VERSION "\n"
1682	               "Board: SF32LB52\n"
1683	               "Touch: %s\n"
1684	               "RTC: %s",
1685	               watch->touch_available ? "Active" : "Unavailable",
1686	               time);
1687	      rtc_ok = true;
1688	    }
1689	  else
1690	    {
1691	      snprintf(about, sizeof(about),
1692	               "AI Watch v" AI_WATCH_VERSION "\n"
1693	               "Board: SF32LB52\n"
1694	               "Touch: %s\n"
1695	               "RTC: Not set",
1696	               watch->touch_available ? "Active" : "Unavailable");
1697	    }
1698	
1699	  lv_label_set_text(watch->about_label, about);
1700	
1701	  if (rtc_ok)
1702	    {
1703	      watch->rtc_valid = true;
1704	      watch->displayed_second = ts.tv_sec;
1705	    }
1706	  else
1707	    {
1708	      watch->rtc_valid = false;
1709	      watch->rtc_warning_printed = true;
1710	      printf("RTC time is not set; waiting for time synchronization\n");
1711	    }
1712	}
