1732	/****************************************************************************
1733	 * Private Functions - Button Input
1734	 ****************************************************************************/
1735	
1736	static int ai_watch_button_initialize(FAR struct ai_watch_s *watch)
1737	{
1738	  btn_buttonset_t sample;
1739	  ssize_t nread;
1740	  int ret;
1741	
1742	  watch->button_fd = open(AI_WATCH_BUTTON_DEVICE, O_RDONLY | O_NONBLOCK);
1743	  if (watch->button_fd < 0)
1744	    {
1745	      int errcode = errno;
1746	
1747	      printf("ERROR: Failed to open %s: %d\n",
1748	             AI_WATCH_BUTTON_DEVICE, errcode);
1749	      return -errcode;
1750	    }
1751	
1752	  ret = ioctl(watch->button_fd, BTNIOC_SUPPORTED,
1753	              (unsigned long)((uintptr_t)&watch->supported_buttons));
1754	  if (ret < 0)
1755	    {
1756	      int errcode = errno;
1757	
1758	      printf("ERROR: BTNIOC_SUPPORTED failed: %d\n", errcode);
1759	      close(watch->button_fd);
1760	      watch->button_fd = -1;
1761	      return -errcode;
1762	    }
1763	
1764	  nread = read(watch->button_fd, &sample, sizeof(sample));
1765	  if (nread != sizeof(sample))
1766	    {
1767	      int errcode = nread < 0 ? errno : EIO;
1768	
1769	      printf("ERROR: Initial button read failed: %d\n", errcode);
1770	      close(watch->button_fd);
1771	      watch->button_fd = -1;
1772	      return -errcode;
1773	    }
1774	
1775	  clock_gettime(CLOCK_MONOTONIC, &watch->next_button_poll);
1776	  watch->button_raw_since = watch->next_button_poll;
1777	  watch->button_raw_pressed = (sample & AI_WATCH_BUTTON_KEY2) != 0;
1778	  watch->button_armed = !watch->button_raw_pressed;
1779	
1780	  printf("Supported buttons: 0x%02lx\n",
1781	         (unsigned long)watch->supported_buttons);
1782	  printf("KEY2 button monitor started\n");
1783	  return OK;
1784	}
1785	
1786	static void ai_watch_button_update(FAR struct ai_watch_s *watch,
1787	                                   FAR const struct timespec *now)
1788	{
1789	  btn_buttonset_t sample;
1790	  bool pressed;
1791	  ssize_t nread;
1792	
1793	  if (watch->button_fd < 0 ||
1794	      !ai_watch_deadline_reached(now, &watch->next_button_poll))
1795	    {
1796	      return;
1797	    }
1798	
1799	  watch->next_button_poll = *now;
1800	  ai_watch_advance_deadline(&watch->next_button_poll,
1801	                            AI_WATCH_BUTTON_POLL_MS);
1802	
1803	  nread = read(watch->button_fd, &sample, sizeof(sample));
1804	  if (nread != sizeof(sample))
1805	    {
1806	      if (nread < 0 && errno != EAGAIN && errno != EINTR)
1807	        {
1808	          printf("ERROR: Button read failed: %d\n", errno);
1809	        }
1810	
1811	      return;
1812	    }
1813	
1814	  pressed = (sample & AI_WATCH_BUTTON_KEY2) != 0;
1815	  if (pressed != watch->button_raw_pressed)
1816	    {
1817	      watch->button_raw_pressed = pressed;
1818	      watch->button_raw_since = *now;
1819	    }
1820	
1821	  if (pressed)
1822	    {
1823	      if (watch->button_armed)
1824	        {
1825	          watch->button_armed = false;
1826	
1827	          if (watch->current_page == AI_WATCH_PAGE_HOME)
1828	            {
1829	              ai_watch_update_bt_state(watch, !watch->bt_state);
1830	              printf("KEY2 pressed: BT %s\n",
1831	                     watch->bt_state ? "ON" : "OFF");
1832	            }
1833	          else
1834	            {
1835	              ai_watch_pop_page(watch);
1836	              printf("KEY2 pressed: Back\n");
1837	            }
1838	        }
1839	    }
1840	  else if (ai_watch_elapsed_ms(now, &watch->button_raw_since) >=
1841	           AI_WATCH_BUTTON_RELEASE_MS)
1842	    {
1843	      watch->button_armed = true;
1844	    }
1845	}
