1847	/****************************************************************************
1848	 * Private Functions - Time Update
1849	 ****************************************************************************/
1850	
1851	static void ai_watch_time_update(FAR struct ai_watch_s *watch)
1852	{
1853	  char date[32];
1854	  char time_hm[8];
1855	  char time_sec[8];
1856	  char dow[8];
1857	  char about[128];
1858	  struct timespec ts;
1859	  struct tm tm;
1860	  static const char *day_names[] =
1861	  {
1862	    "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"
1863	  };
1864	
1865	  if (clock_gettime(CLOCK_REALTIME, &ts) < 0 ||
1866	      localtime_r(&ts.tv_sec, &tm) == NULL ||
1867	      tm.tm_year + 1900 < AI_WATCH_RTC_MIN_YEAR)
1868	    {
1869	      if (!watch->rtc_warning_printed)
1870	        {
1871	          printf("RTC time is not set; waiting for time synchronization\n");
1872	          watch->rtc_warning_printed = true;
1873	        }
1874	
1875	      if (watch->rtc_valid)
1876	        {
1877	          lv_label_set_text(watch->time_label, "--:--");
1878	          lv_label_set_text(watch->seconds_label, ":--");
1879	          lv_label_set_text(watch->date_label, "----/--/--");
1880	          lv_label_set_text(watch->dow_label, "");
1881	          watch->rtc_valid = false;
1882	
1883	          snprintf(about, sizeof(about),
1884	                   "AI Watch v" AI_WATCH_VERSION "\n"
1885	                   "Board: SF32LB52\n"
1886	                   "Touch: %s\n"
1887	                   "RTC: Not set",
1888	                   watch->touch_available ? "Active" : "Unavailable");
1889	          lv_label_set_text(watch->about_label, about);
1890	        }
1891	
1892	      return;
1893	    }
1894	
1895	  watch->rtc_valid = true;
1896	  if (ts.tv_sec == watch->displayed_second)
1897	    {
1898	      return;
1899	    }
1900	
1901	  watch->displayed_second = ts.tv_sec;
1902	
1903	  strftime(time_hm, sizeof(time_hm), "%H:%M", &tm);
1904	  snprintf(time_sec, sizeof(time_sec), ":%02d", tm.tm_sec);
1905	  strftime(date, sizeof(date), "%Y/%m/%d", &tm);
1906	
1907	  int wday = ai_watch_day_of_week(tm.tm_year + 1900,
1908	                                  tm.tm_mon + 1, tm.tm_mday);
1909	
1910	  snprintf(dow, sizeof(dow), "%s", day_names[wday]);
1911	
1912	  lv_label_set_text(watch->time_label, time_hm);
1913	  lv_label_set_text(watch->seconds_label, time_sec);
1914	  lv_label_set_text(watch->date_label, date);
1915	  lv_label_set_text(watch->dow_label, dow);
1916	
1917	  snprintf(about, sizeof(about),
1918	           "AI Watch v" AI_WATCH_VERSION "\n"
1919	           "Board: SF32LB52\n"
1920	           "Touch: %s\n"
1921	           "RTC: %s",
1922	           watch->touch_available ? "Active" : "Unavailable",
1923	           time_hm);
1924	  lv_label_set_text(watch->about_label, about);
1925	}
