1927	/****************************************************************************
1928	 * Private Functions - Touch Input
1929	 ****************************************************************************/
1930	
1931	static void ai_watch_touch_update(FAR struct ai_watch_s *watch)
1932	{
1933	  lv_indev_state_t state;
1934	  lv_point_t point;
1935	  struct timespec now;
1936	
1937	  if (watch->touch_indev == NULL || !watch->touch_available)
1938	    {
1939	      return;
1940	    }
1941	
1942	  state = lv_indev_get_state(watch->touch_indev);
1943	  lv_indev_get_point(watch->touch_indev, &point);
1944	  clock_gettime(CLOCK_MONOTONIC, &now);
1945	
1946	  if (state == LV_INDEV_STATE_PRESSED)
1947	    {
1948	      if (!watch->touch_active)
1949	        {
1950	          watch->touch_active = true;
1951	          watch->touch_start_x = point.x;
1952	          watch->touch_start_y = point.y;
1953	          watch->touch_start_time = now;
1954	        }
1955	    }
1956	  else if (watch->touch_active)
1957	    {
1958	      int dx = point.x - watch->touch_start_x;
1959	      int dy = point.y - watch->touch_start_y;
1960	      int64_t elapsed_ms =
1961	          ai_watch_elapsed_ms(&now, &watch->touch_start_time);
1962	
1963	      watch->touch_active = false;
1964	
1965	      if (elapsed_ms > AI_WATCH_SWIPE_TIMEOUT_MS)
1966	        {
1967	          return;
1968	        }
1969	
1970	      /* Only process gesture on HOME page.
1971	       * Menu page: hex menu container handles all touches.
1972	       * Other pages: back via KEY2 or on-screen buttons.
1973	       */
1974	
1975	      if (watch->current_page != AI_WATCH_PAGE_HOME)
1976	        {
1977	          return;
1978	        }
1979	
1980	      if (abs(dy) > AI_WATCH_SWIPE_THRESHOLD && abs(dy) > abs(dx))
1981	        {
1982	          if (dy < 0)
1983	            {
1984	              ai_watch_push_page(watch, AI_WATCH_PAGE_APP_LIST);
1985	            }
1986	        }
1987	      else if (abs(dx) < AI_WATCH_SWIPE_THRESHOLD &&
1988	               abs(dy) < AI_WATCH_SWIPE_THRESHOLD)
1989	        {
1990	          ai_watch_push_page(watch, AI_WATCH_PAGE_APP_LIST);
1991	        }
1992	    }
1993	}
