1998	
1999	int main(int argc, FAR char *argv[])
2000	{
2001	  lv_nuttx_result_t result;
2002	  lv_nuttx_dsc_t info;
2003	  struct ai_watch_s watch =
2004	  {
2005	    .button_fd = -1,
2006	    .displayed_second = -1,
2007	    .current_page = AI_WATCH_PAGE_HOME,
2008	    .current_theme = AI_WATCH_THEME_DARK,
2009	    .touch_indev = NULL,
2010	    .touch_available = false,
2011	    .page_stack_top = 0,
2012	    .app_page_screen = NULL,
2013	    .active_app_index = -1,
2014	    .timer =
2015	    {
2016	      .update_timer = NULL,
2017	      .start_tick = 0,
2018	      .elapsed_ms = 0,
2019	      .running = false,
2020	      .time_label = NULL,
2021	    },
2022	    .menu =
2023	    {
2024	      .container = NULL,
2025	      .icon_count = 0,
2026	      .scroll_x = 0.0f,
2027	      .scroll_y = 0.0f,
2028	      .dragging = false,
2029	      .focused_index = 0,
2030	      .snapping = false,
2031	    },
2032	  };
2033	
2034	  printf("AI Watch version %s\n", AI_WATCH_VERSION);
2035	  printf("ai_watch started\n");
2036	
2037	  /* Wait for LCD device (mandatory).  Touch will be added later. */
2038	
2039	  int retry;
2040	
2041	  for (retry = 0; retry < 50; retry++)
2042	    {
2043	      if (access("/dev/lcd0", F_OK) == 0)
2044	        {
2045	          printf("LCD device ready after %d ms\n", retry * 100);
2046	          break;
2047	        }
2048	
2049	      usleep(100000);
2050	    }
2051	
2052	  if (retry >= 50)
2053	    {
2054	      printf("ERROR: /dev/lcd0 not found after 5s\n");
2055	      return EXIT_FAILURE;
2056	    }
2057	
2058	  if (lv_is_initialized())
2059	    {
2060	      printf("ERROR: LVGL is already initialized\n");
2061	      return EXIT_FAILURE;
2062	    }
2063	
2064	  lv_init();
2065	  lv_nuttx_dsc_init(&info);
2066	
2067	  info.fb_path = "/dev/lcd0";
2068	  info.input_path = NULL;  /* skip touch — added later when ready */
2069	
2070	  /* Retry lv_nuttx_init — the driver may still be completing
2071	   * the first DMA transfer when /dev/lcd0 first becomes openable.
2072	   */
2073	
2074	  int init_retry;
2075	
2076	  for (init_retry = 0; init_retry < 3; init_retry++)
2077	    {
2078	      lv_nuttx_init(&info, &result);
2079	
2080	      if (result.disp != NULL)
2081	        {
2082	          break;
2083	        }
2084	
2085	      printf("lv_nuttx_init attempt %d failed, retrying...\n",
2086	             init_retry + 1);
2087	      lv_nuttx_deinit(&result);
2088	      lv_deinit();
2089	      usleep(200000); /* 200 ms */
2090	      lv_init();
2091	      lv_nuttx_dsc_init(&info);
2092	      info.fb_path = "/dev/lcd0";
2093	      info.input_path = NULL;
2094	    }
2095	
2096	  if (result.disp == NULL)
2097	    {
2098	      printf("ERROR: LVGL init failed after %d retries\n", init_retry);
2099	      lv_nuttx_deinit(&result);
2100	      lv_deinit();
2101	      return EXIT_FAILURE;
2102	    }
2103	
2104	  printf("LVGL initialized, display ready\n");
2105	
2106	  /* Touch may not be registered yet — try now, poll later if not */
2107	
2108	  watch.touch_indev = NULL;
2109	  watch.touch_available = false;
2110	  watch.touch_poll_remaining = 30;  /* poll for up to 30s */
2111	
2112	  if (access("/dev/input0", F_OK) == 0)
2113	    {
2114	      watch.touch_indev =
2115	          lv_nuttx_touchscreen_create("/dev/input0");
2116	
2117	      if (watch.touch_indev != NULL)
2118	        {
2119	          watch.touch_available = true;
2120	          watch.touch_poll_remaining = 0;
2121	          printf("Touch input initialized\n");
2122	        }
2123	    }
2124	
2125	  if (!watch.touch_available)
2126	    {
2127	      printf("Touch not ready, will poll every 1s\n");
2128	      clock_gettime(CLOCK_MONOTONIC, &watch.touch_next_poll);
2129	      watch.touch_next_poll.tv_sec += 1;
2130	    }
2131	
2132	  ai_watch_create_ui(&watch);
2133	  ai_watch_button_initialize(&watch);
2134	
2135	  printf("UI created; entering main loop\n");
2136	
2137	  for (; ; )
2138	    {
2139	      struct timespec now;
2140	      uint32_t idle;
2141	
2142	      clock_gettime(CLOCK_MONOTONIC, &now);
2143	
2144	      /* Poll for touch device (every 1s, up to 30 attempts) */
2145	
2146	      if (!watch.touch_available && watch.touch_poll_remaining > 0)
2147	        {
2148	          if (ai_watch_deadline_reached(&now,
2149	                                        &watch.touch_next_poll))
2150	            {
2151	              if (access("/dev/input0", F_OK) == 0)
2152	                {
2153	                  watch.touch_indev =
2154	                      lv_nuttx_touchscreen_create("/dev/input0");
2155	
2156	                  if (watch.touch_indev != NULL)
2157	                    {
2158	                      watch.touch_available = true;
2159	                      watch.touch_poll_remaining = 0;
2160	                      printf("Touch input initialized (delayed)\n");
2161	                    }
2162	                }
2163	
2164	              watch.touch_poll_remaining--;
2165	              watch.touch_next_poll = now;
2166	              watch.touch_next_poll.tv_sec += 1;
2167	            }
2168	        }
2169	
2170	      ai_watch_button_update(&watch, &now);
2171	      ai_watch_touch_update(&watch);
2172	      ai_watch_time_update(&watch);
2173	
2174	      idle = lv_timer_handler();
2175	      if (idle == 0 || idle > AI_WATCH_BUTTON_POLL_MS)
2176	        {
2177	          idle = AI_WATCH_BUTTON_POLL_MS;
2178	        }
2179	
2180	      usleep(idle * 1000);
2181	    }
2182	
2183	  return EXIT_SUCCESS;
2184	}
